from lib import *
S = SS('p54')
steps = [
    step("冷启动(5 次):从 Popen 到调试端口可用,中位 396 ms(各次 457、556、396、366、361);新建标签页并加载一个简单页面,中位 24 ms(各次 26、45、24、24、22)。启动浏览器的代价约是新开一页的 16 倍,所以启动一次、反复开页比每个页面都启动一次浏览器便宜得多。", t=tl(S(1)), done=lidx(S(1), '调试端口可用'), b=bars([['启动浏览器 ms', 396, '396'], ['新开一页并加载 ms', 24, '24']], 400, mark=[0], done=[1]), kv=KV([['冷启动', '中位 396 ms'], ['新标签页加载简单页面', '中位 24 ms'], ['结论', '浏览器要复用,不要每页启动']], ['结论'])),
    step("内存:把进程树里各进程的 RSS 相加(共享内存页会被重复计算,所以偏大,只用来看趋势)。刚启动、0 个标签页:9 个进程(浏览器主进程 1、GPU 进程 1、工具进程 2、渲染进程 5)RSS 之和 1177 MiB;1 个标签页:10 个进程、1325 MiB;5 个标签页:14 个进程、1778 MiB;10 个标签页:19 个进程、2266 MiB。每多一个标签页多一个渲染进程,RSS 之和约多 109 MiB(10 个标签页比 0 个多 1089 MiB)。", t=tl(S(2)), done=lidx(S(2), '         0', '        10'), mark=lidx(S(2), '         5'), b=bars([['0 个标签页 MiB', 1177, '1177'], ['1 个', 1325, '1325'], ['5 个', 1778, '1778'], ['10 个', 2266, '2266']], 2300, done=[3]), kv=KV([['0 个标签页', '9 个进程,约 1177 MiB'], ['10 个标签页', '19 个进程,约 2266 MiB'], ['每个标签页', '+1 个渲染进程,约 +109 MiB']], ['每个标签页'])),
    step("同一站点的新标签页和不同站点的新标签页,渲染进程数增长一样吗:1 个站点 × 1 页:10 个进程、6 个渲染进程;同一站点再开 4 页(共 5 页):14 个进程、10 个渲染进程;再开 4 个不同站点各 1 页:18 个进程、14 个渲染进程;再加 5 个不同站点各 1 页:23 个进程、19 个渲染进程。每多一个标签页都多 1 个渲染进程,不论是同一站点还是不同站点(这里的页面都是通过 CDP 新建的标签页);RSS 之和从 1309 MiB 涨到 3009 MiB。", t=tl(S(3)), done=lidx(S(3), '同一站点再开 4 页', '4 个不同站点', '再加 5 个不同站点'), mark=lidx(S(3), '1 个站点 × 1 页'), b=bars([['1 个站点×1 页:渲染进程', 6, '6'], ['同站点共 5 页', 10, '10'], ['再加 4 个不同站点', 14, '14'], ['再加 5 个不同站点', 19, '19']], 19, done=[1, 2, 3]), kv=KV([['同一站点 +4 页', '渲染进程 +4'], ['不同站点 +4 页', '渲染进程 +4'], ['结论', '进程数随标签页数线性增长']], ['结论'])),
    step("不下载图片和样式能省多少(一个含 20 张各 100 KB 图片和一个 50 KB 样式表的页面,各 5 次取中位数):不拦截:加载 31 ms,传输 2052 KiB;用 CDP 的 Network.setBlockedURLs 拦截 *.png 和 *.css:加载 13 ms,传输 1 KiB,被拦截的请求 21 个(20 张图片加 1 个样式表)。流量和时间都少了。", t=tl(S(4)), done=lidx(S(4), '拦截 *.png'), mark=lidx(S(4), '不拦截'), b=bars([['不拦截 传输 KiB', 2052, '2052'], ['拦截 传输 KiB', 1, '1'], ['不拦截 加载 ms', 31, '31'], ['拦截 加载 ms', 13, '13']], 2100, mark=[0], done=[1]), kv=KV([['不拦截', '31 ms,2052 KiB'], ['拦截图片与样式', '13 ms,1 KiB'], ['被拦截的请求', '21 个']], ['拦截图片与样式'])),
]
A = mkartp('p54', 54, '爬虫,headless Chrome,CDP,启动耗时,内存,标签页,资源拦截,Python,真实验证,动画演示',
    '实测 headless Chrome 154 的开销:冷启动到调试端口可用中位 396 ms,新开标签页加载简单页面 24 ms;0 个标签页就有 9 个进程、RSS 之和约 1177 MiB,每多一个标签页多一个渲染进程、约 +109 MiB(同一站点与不同站点一样);用 CDP 拦截图片和样式让加载从 31 ms/2052 KiB 降到 13 ms/1 KiB。',
    '用浏览器渲染页面比 requests 重得多:启动要多久、每个标签页占多少内存、一个页面里的图片和样式要不要加载,这些决定了你的爬虫一台机器能同时开多少页面。这篇在本机量一量 headless Chrome 的启动耗时、进程与内存,以及资源拦截的收益。',
    [('396 对 24 ms', '启动浏览器与新开一个标签页加载简单页面的耗时(中位数)'), ('约 +109 MiB', '每多开一个标签页,进程树 RSS 之和增加的量(共享内存重复计算,偏大)'), ('2052 → 1 KiB', '拦截图片和样式表后,同一个页面的传输量')],
    [('启动', '<p>从启动进程到调试端口可用约 396 ms,之后新开一页并加载简单页面只要约 24 ms。所以浏览器应当启动一次、反复开页。</p>'),
     ('内存', '<p>刚启动就有 9 个进程(浏览器主进程、GPU 进程、工具进程和几个渲染进程),RSS 之和约 1177 MiB;每多一个标签页多一个渲染进程,多约 109 MiB。把各进程的 RSS 相加会重复计算共享内存,实际占用比这个数小,但趋势是线性增长。</p>'),
     ('进程与站点', '<p>在这个实验里,新标签页不管是同一站点还是不同站点,渲染进程数都是每页 +1(通过 CDP 新建的标签页)。我没有测同一标签页内的 iframe 或 window.open 打开的页面是否共享渲染进程。</p>'),
     ('拦截资源', '<p>用 <code>Network.setBlockedURLs</code> 拦截图片和样式表,传输量从 2052 KiB 降到 1 KiB,加载从 31 ms 降到 13 ms。拦截样式和图片可能让依赖它们的页面逻辑(布局判断、懒加载)失效,这点没有测。</p>')],
    steps,
    [ENV_P + '。Chrome 154.0.8037.98 通过 pcdp.py 启动(--headless=new、独立 --user-data-dir、--no-sandbox、--disable-gpu、--disable-extensions 等),调试端口只监听 127.0.0.1;进程树与 RSS 来自 ps -axo pid=,ppid=,rss=,command=,从 Chrome 主进程起递归取所有子孙进程,按命令行里的 --type 区分种类;RSS 之和重复计算共享页,偏大;冷启动 5 次,拦截对比每组 5 次取中位数;每次实验后按唯一的 user-data-dir 结束这批 Chrome 进程',
     '没有验证:Linux 容器里的资源占用与 --disable-dev-shm-usage 等参数;chrome-headless-shell 这种精简版的开销;--single-process、--renderer-process-limit 等降低进程数的参数;真实复杂页面的内存;Firefox 或 WebKit 的开销;用 footprint 等工具得到更准确的内存;页面关闭后内存是否释放(下一篇讨论复用)'],
    '启动耗时与内存')
